const draft = $("Build Draft Message").last().json;
let binary = {};
try {
  binary = $("Input With Images").first(0, 0).binary || {};
} catch (e) {
  binary = {};
}
return [{ json: draft, binary }];

// Повторно подаване на съобщението на потребителя заедно със снимките му
const last = $("Input With Images").last().json;
const problems = $("Count Attempt").last().json.problems;
const text = last.text + (problems ? "\n\n[Системна забележка: предишната чернова беше невалидна: " + problems + ". Поправи я или попитай потребителя за липсващото.]" : "");
return [{ json: { text, sessionId: last.sessionId, memoryKey: last.memoryKey }, binary: $("Input With Images").first(0, 0).binary || {} }];

// Тестовите данни са в Data Tables: orders_eval_dataset (съобщения и очаквани резултати) и orders_eval_images (снимки).
// Този нод само сглобява реда от dataset-а във вход както от Chat Trigger (текст + снимки). Няма вградени данни.
let row;
try {
  row = $("Evaluation Trigger").first().json;
} catch (e) {
  row = $("When Called By Eval Runner").first().json;
}
const library = {};
for (const r of $("Get Eval Images").all()) {
  library[r.json.image_name] = r.json;
}
const names = String(row.images || "").split(",").map((s) => s.trim()).filter(Boolean);
const binary = {};
for (let i = 0; i < names.length; i++) {
  const img = library[names[i]];
  if (!img) throw new Error("Unknown eval image: " + names[i]);
  binary["data" + i] = await this.helpers.prepareBinaryData(Buffer.from(img.base64, "base64"), names[i] + ".jpg", img.mime_type || "image/jpeg");
}
const { images, ...rest } = row;
return [{
  json: {
    chatInput: String(row.text || ""),
    sessionId: "eval-" + row.case_id + "-" + Date.now(),
    evalMode: true,
    runner: row.runner === true,
    case: rest,
    imageNames: names
  },
  binary
}];
